package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.temporal.Temporal
import io.circe.Json
import io.circe.syntax._
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

// ============================================================================
// Protocol Definitions
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed abstract class TokenType(val value: String)
object TokenType {
  case object STRING extends TokenType("string")
  case object NUMERIC extends TokenType("numeric")
  case object TEMPORAL extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY extends TokenType("binary")
  case object NULL extends TokenType("null")
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(value: String, tokenType: TokenType, metadata: Map[String, Any] = Map.empty) {
  def withMetadata(entries: (String, Any)*): Token = {
    copy(metadata = metadata ++ entries)
  }
}

class MutableTokenBatch {
  private val _tokens = mutable.ListBuffer[Token]()
  private var _processed: Boolean = false

  def tokens: Seq[Token] = _tokens.toSeq

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector

  def getAll: Seq[T] = _items

  def mapTokens(func: T => String): Seq[String] = _items.map(func)

  def size: Int = _items.size
}

class TokenSink[-T] {
  private val _received = mutable.ListBuffer[Any]()

  def receive(item: T): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

class BivariantHandler[T](default: T) {
  private var _value: T = default

  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  def tokenize(value: Either[String, Array[Byte]]): Token = {
    value match {
      case Left(s) => tokenizeString(s)
      case Right(b) => tokenizeBytes(b)
    }
  }

  def tokenizeString(value: String): Token = {
    Token(normalizer(value), TokenType.STRING)
  }

  def tokenizeBytes(value: Array[Byte]): Token = {
    val strValue = new String(value, encoding)
    Token(normalizer(strValue), TokenType.STRING)
  }
}

class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] { 

  def tokenize(value: Any): Token = {
    val (strValue, typeName) = value match {
      case d: BigDecimal => (f"$d%.${precision}f", "BigDecimal")
      case f: Float => (f"$f%.${precision}f", "Float")
      case d: Double => (f"$d%.${precision}f", "Double")
      case i: Int => (i.toString, "Int")
      case l: Long => (l.toString, "Long")
      case other => (other.toString, other.getClass.getSimpleName)
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> typeName))
  }
}

class TemporalTokenizer(
    formatStr: Option[String] = None
) extends BaseTokenizer[Temporal] {

  private val IsoFormat = java.time.format.DateTimeFormatter.ISO_LOCAL_DATE_TIME
  private val DateFormat = java.time.format.DateTimeFormatter.ISO_LOCAL_DATE

  private val customFormatter = formatStr.map(java.time.format.DateTimeFormatter.ofPattern)

  def tokenize(value: Temporal): Token = {
    val fmt = customFormatter.getOrElse {
      value match {
        case _: LocalDateTime => IsoFormat
        case _: LocalDate => DateFormat
        case _ => IsoFormat // Fallback
      }
    }

    val strValue = try {
      fmt.format(value)
    } catch {
      case _: Exception => value.toString
    }

    Token(strValue, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Universal Tokenizer
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: Any): Token = {
    value match {
      case null => tokenizeNull
      case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)
      case s: String => stringTokenizer.tokenizeString(s)
      case b: Array[Byte] => stringTokenizer.tokenizeBytes(b)
      case i: Int => numericTokenizer.tokenize(i)
      case l: Long => numericTokenizer.tokenize(l)
      case f: Float => numericTokenizer.tokenize(f)
      case d: Double => numericTokenizer.tokenize(d)
      case bd: BigDecimal => numericTokenizer.tokenize(bd)
      case ld: LocalDate => temporalTokenizer.tokenize(ld)
      case ldt: LocalDateTime => temporalTokenizer.tokenize(ldt)
      case t: Temporal => temporalTokenizer.tokenize(t)
      case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
    }
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

class TokenRegistry[T] {
  private val _registry = mutable.Map[String, TokenContainer[T]]()
  private val _handlers = mutable.ListBuffer[T => Option[Token]]()

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.view.map(h => h(item)).collectFirst { case Some(t) => t }
        }.toList
    }
  }
}

// ============================================================================
// Higher-Kinded Type Simulation
// ============================================================================

class TokenFunctor[T](val _value: T) {

  def map[U](func: T => U): TokenFunctor[U] = {
    new TokenFunctor(func(_value))
  }

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = {
    func(_value)
  }

  def getOrElse(default: T): T = {
    if (_value != null) _value else default
  }

  def get: T = _value
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    new TokenMonad(funcWrapped._value(this._value))
  }
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.")

    def traverse(current: Json, remaining: List[String]): Option[Json] = {
      remaining match {
        case Nil => Some(current)
        case head :: tail =>
          if (current.isObject) {
            current.asObject.flatMap(_(head)).flatMap(traverse(_, tail))
          } else if (current.isArray && head.forall(_.isDigit)) {
            val idx = head.toInt
            current.asArray.flatMap(arr => if (idx >= 0 && idx < arr.length) Some(arr(idx)) else None)
              .flatMap(traverse(_, tail))
          } else {
            None
          }
      }
    }

    traverse(value, parts.toList).map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation = ".,!?;:'\"()[]{}"

  private def processToken(word: String): Option[String] = {
    var processed = word
    if (stripPunctuation) {
      val pSet = punctuation.toSet
      processed = processed.dropWhile(pSet.contains).reverse.dropWhile(pSet.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) return None

    if (maxLength.exists(max => processed.length > max)) {
      processed = processed.substring(0, maxLength.get)
    }

    if (processed.isEmpty) None else Some(processed)
  }

  def tokenize(text: String): List[Token] = {
    text.split("\\s+").zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer[(String, Int, Int)]()
    var currentPos = 0
    val words = text.split("\\s+") 

    for (word <- words if word.nonEmpty) {
       val start = text.indexOf(word, currentPos)
       if (start != -1) {
         val end = start + word.length
         processToken(word).foreach { processed =>
           result += ((processed, start, end))
         }
         currentPos = end
       }
    }
    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder Pattern
// ============================================================================

class TokenizerBuilder[T] {
  private val _normalizers = mutable.ListBuffer[String => String]()
  private val _validators = mutable.ListBuffer[T => Boolean]()
  private var _metadata = Map[String, Any]()

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    _normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    _validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    _metadata ++= entries
    this
  }

  def build(): T => Token = {
    val normalizers = _normalizers.toList
    val validators = _validators.toList
    val metadata = _metadata

    (value: T) => {
      validators.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString

      normalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, metadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

