      case bd: BigDecimal => numericTokenizer.tokenize(bd)
      case ld: LocalDate => temporalTokenizer.tokenize(ld)
      case ldt: LocalDateTime => temporalTokenizer.tokenize(ldt)
      case t: Temporal => temporalTokenizer.tokenize(t)
      case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
    }
  }
}

// ============================================================================ 
// Complex Nested Generics
// ============================================================================ 

class TokenRegistry[T] {
  private val _registry = mutable.Map[String, TokenContainer[T]]()
  private val _handlers = mutable.ListBuffer[T => Option[Token]]()

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry(key) = container
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map {
          item =>
          _handlers.view.map(h => h(item)).collectFirst { case Some(t) => t }
        }.toList
    }
  }
}

// ============================================================================ 
// Higher-Kinded Type Simulation
// ============================================================================ 

class TokenFunctor[T](val _value: T) {

  def map[U](func: T => U): TokenFunctor[U] = {
    new TokenFunctor(func(_value))
  }

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = {
    func(_value)
  }

  def getOrElse(default: T): T = {
    if (_value != null) _value else default
  }

  def get: T = _value
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    new TokenMonad(funcWrapped._value(this._value))
  }
}

// ============================================================================ 
// JSON Structure Tokenization
// ============================================================================ 

class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.")

    def traverse(current: Json, remaining: List[String]): Option[Json] = {
      remaining match {
        case Nil => Some(current)
        case head :: tail =>
          if (current.isObject) {
            current.asObject.flatMap(_(head)).flatMap(traverse(_, tail))
          } else if (current.isArray && head.forall(_.isDigit)) {
            val idx = head.toInt
            current.asArray.flatMap(arr => if (idx >= 0 && idx < arr.length) Some(arr(idx)) else None)
              .flatMap(traverse(_, tail))
          } else {
            None
          }
      }
    }

    traverse(value, parts.toList).map(tokenize)
  }
}

// ============================================================================ 
// Whitespace Tokenizer
// ============================================================================ 

class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation = ".,!?;:'\"()[]{}"

  private def processToken(word: String): Option[String] = {
    var processed = word
    if (stripPunctuation) {
      val pSet = punctuation.toSet
      processed = processed.dropWhile(pSet.contains).reverse.dropWhile(pSet.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) return None

    if (maxLength.exists(max => processed.length > max)) {
      processed = processed.substring(0, maxLength.get)
    }

    if (processed.isEmpty) None else Some(processed)
  }

  def tokenize(text: String): List[Token] = {
    text.split("\\s+").zipWithIndex.flatMap {
      case (word, i) =>
      processToken(word).map {
        processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = {
    tokenize(text).map(_.value)
  }

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer[(String, Int, Int)]()
    var currentPos = 0
    val words = text.split("\\s+") 

    for (word <- words if word.nonEmpty) {
       val start = text.indexOf(word, currentPos)
       if (start != -1) {
         val end = start + word.length
         processToken(word).foreach {
           processed =>
           result += ((processed, start, end))
         }
         currentPos = end
       }
    }
    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================ 
// Builder Pattern
// ============================================================================ 

class TokenizerBuilder[T] {
  private val _normalizers = mutable.ListBuffer[String => String]()
  private val _validators = mutable.ListBuffer[T => Boolean]()
  private var _metadata = Map[String, Any]()

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    _normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    _validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    _metadata ++= entries
    this
  }

  def build(): T => Token = {
    val normalizers = _normalizers.toList
    val validators = _validators.toList
    val metadata = _metadata

    (value: T) => {
      validators.foreach {
        validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      var strValue = value.toString

      normalizers.foreach {
        normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, metadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}
